import java.util.Scanner;
public class JFailCourse2 {
	public static void main(String[] args) {
		//Alkhutwa 1: Qira madkholat almodarris
		Scanner scan = new Scanner(System.in);
		System.out.println("Adkhil darajat alimtihan:");
		int examScore = scan.nextInt();
		System.out.println("Adkhil ma idha kana alttalib qad ghash (true aw false):");
		boolean hasCheated = scan.nextBoolean();		
		scan.close();
		//Alkhutwa 2: Uktub alta'bir booleani li tahdid idha alttalib yarsub fi almuqarrar
		boolean isFailing = examScore < 55 || hasCheated;
		System.out.println(isFailing);
	}
